{"file_path":"src/address.js","content":"/**
 * Cell address handling: column-letter <-> column-number conversion, and
 * parsing an arbitrary "word" (letters followed by digits) into its
 * column/row components, whether or not it falls inside the addressable
 * range (columns A..ZZ, rows 1..999).
 */

const MAX_COL = 26 * 26 + 26 // ZZ
const MAX_ROW_DIGITS = 3

export function colLettersToNumber(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function colNumberToLetters(num) {
  let s = ''
  let n = num
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse a word (letters then digits, already or not upper-cased) into its
 * address components. `col`/`row` are always numeric when the digit part is
 * present; `inRange` says whether the address falls in the addressable
 * range A1..ZZ999.
 */
export function parseWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const digits = m[2]
  const col = colLettersToNumber(letters)
  const row = digits.length > 0 ? parseInt(digits, 10) : null
  const inRange =
    letters.length <= 2 &&
    digits.length >= 1 &&
    digits.length <= MAX_ROW_DIGITS &&
    row !== null &&
    row >= 1
  return { letters, digits, col, row, inRange }
}

export function isAddressableCell(col, row) {
  return col >= 1 && col <= MAX_COL && row >= 1 && row <= 10 ** MAX_ROW_DIGITS - 1
}

export function cellKey(col, row) {
  return `${colNumberToLetters(col)}${row}`
}
"}

