{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for a formula body (the part of a cell's content after the
 * leading `=`).
 */

export class LexError extends Error {}

const SIMPLE = {
  '(': 'LPAREN',
  ')': 'RPAREN',
  ',': 'COMMA',
  '^': 'CARET',
  '*': 'STAR',
  '/': 'SLASH',
  '+': 'PLUS',
  '-': 'MINUS',
}

export function tokenize(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    if (ch in SIMPLE) {
      tokens.push({ type: SIMPLE[ch] })
      i++
      continue
    }
    if (ch === '=') {
      tokens.push({ type: 'EQ' })
      i++
      continue
    }
    if (ch === '<') {
      if (body[i + 1] === '>') {
        tokens.push({ type: 'NE' })
        i += 2
      } else if (body[i + 1] === '=') {
        tokens.push({ type: 'LE' })
        i += 2
      } else {
        tokens.push({ type: 'LT' })
        i += 1
      }
      continue
    }
    if (ch === '>') {
      if (body[i + 1] === '=') {
        tokens.push({ type: 'GE' })
        i += 2
      } else {
        tokens.push({ type: 'GT' })
        i += 1
      }
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(body.slice(i))
      tokens.push({ type: 'NUMBER', text: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(body.slice(i))
      tokens.push({ type: 'WORD', text: m[0] })
      i += m[0].length
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

