chunk.argumentsDelta:
{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for a formula body's token stream, producing an
 * AST. Precedence, loosest to tightest: comparisons, then `+`/`-`, then
 * `*`/`/`, then `^` (right-associative), then a leading unary `+`/`-`
 * (which binds tighter than `^`). A range (`A1:B3`) is only accepted
 * directly as a function argument.
 */

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const CMP_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const OP_TEXT = { EQ: '=', NE: '<>', LT: '<', LE: '<=', GT: '>', GE: '>=' }

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset] ?? { type: 'EOF' }
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const tok = this.next()
    if (tok.type !== type) throw new ParseError(`expected ${type}, got ${tok.type}`)
    return tok
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (CMP_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { type: 'binary', op: OP_TEXT[op], left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek().type === 'PLUS' || this.peek().type === 'MINUS') {
      const op = this.next().type === 'PLUS' ? '+' : '-'
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek().type === 'STAR' || this.peek().type === 'SLASH') {
      const op = this.next().type === 'STAR' ? '*' : '/'
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.peek().type === 'CARET') {
      this.next()
      const right = this.parsePower()
      return { type: 'binary', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    if (this.peek().type === 'PLUS' || this.peek().type === 'MINUS') {
      const op = this.next().type === 'PLUS' ? '+' : '-'
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const tok = this.peek()
    if (tok.type === 'NUMBER') {
      this.next()
      return { type: 'number', value: parseFloat(tok.text) }
    }
    if (tok.type === 'LPAREN') {
      this.next()
      const inner = this.parseComparison()
      this.expect('RPAREN')
      return inner
    }
    if (tok.type === 'WORD') {
      this.next()
      const word = tok.text.toUpperCase()
      if (word === 'TRUE') return { type: 'bool', value: true }
      if (word === 'FALSE') return { type: 'bool', value: false }
      if (this.peek().type === 'LPAREN') {
        this.next()
        const args = []
        if (this.peek().type !== 'RPAREN') {
          args.push(this.parseArgument())
          while (this.peek().type === 'COMMA') {
            this.next()
            args.push(this.parseArgument())
          }
        }
        this.expect('RPAREN')
        return { type: 'call', name: word, args }
      }
      return { type: 'address', word }
    }
    throw new ParseError(`unexpected token ${tok.type}`)
  }

  parseArgument() {
    if (this.peek().type === 'WORD' && this.peek(1).type === 'COLON') {
      const from = this.next().text.toUpperCase()
      this.expect('COLON')
      const toTok = this.peek()
      if (toTok.type !== 'WORD') throw new ParseError('expected address after :')
      this.next()
      const to = toTok.text.toUpperCase()
      return { type: 'range', from, to }
    }
    return this.parseComparison()
  }
}

/**
 * Parse a formula body (without the leading `=`) into an AST, or return
 * null if the grammar rejects it.
 */
export function parseFormula(body) {
  try {
    const tokens = tokenize(body)
    const parser = new Parser(tokens)
    const ast = parser.parseComparison()
    if (parser.peek().type !== 'EOF') throw new ParseError('trailing tokens')
    return ast
  } catch (err) {
    if (err instanceof ParseError || err instanceof LexError) return null
    throw err
  }
}
"}

