{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for a formula body's token stream, producing an
 * AST. Precedence, loosest to tightest: comparisons, then `+`/`-`, then
 * `*`/`/`, then `^` (right-associative), then a leading unary `+`/`-`
 * (which binds tighter than `^`). A range (`A1:B3`) is only accepted
 * directly as a function argument.
 */

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const CMP_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const OP_TEXT = { EQ: '=', NE: '<>', LT: '<', LE: '<=', GT: '>', GE: '>=' }

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset] ?? { type: 'EOF' }
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const tok = this.next()
    if (tok.type !== type) throw new ParseError(`expected ${type}, got ${tok.type}`)
    return tok
  }

