    let left = this.parseAdditive()
    while (CMP_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      left = { type: 'binary', op: OP_TEXT[op], left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek().type === 'PLUS' || this.peek().type === 'MINUS') {
      const op = this.next().type === 'PLUS' ? '+' : '-'
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek().type === 'STAR' || this.peek().type === 'SLASH') {
      const op = this.next().type === 'STAR' ? '*' : '/'
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.peek().type === 'CARET') {
      this.next()
      const right = this.parsePower()
      return { type: 'binary', op: '^', left: base, right }
    }
    return base
  }

  parseUnary() {
    if (this.peek().type === 'PLUS' || this.peek().type === 'MINUS') {
      const op = this.next().type === 'PLUS' ? '+' : '-'
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

