{"file_path":"src/sheet.js","content":"/**
 * Parses a whole sheet (the standard input text) into a map of declared
 * cells, validating addresses and rejecting duplicates.
 */

import { parseWord } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Returns a Map from canonical address (e.g. "A1") to { content, col, row }.
 * Throws SheetError on the first invalid address or duplicate declaration.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  lines.forEach((rawLine, idx) => {
    const lineNo = idx + 1
    const stripped = rawLine.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = /^(\S+)(?:[ \t]+(.*))?$/.exec(stripped)
    const rawAddress = m[1]
    const content = m[2] ?? ''

    const address = rawAddress.toUpperCase()
    const parsed = parseWord(address)
    if (!parsed || parsed.letters.length !== address.length - parsed.digits.length || !parsed.inRange) {
      throw new SheetError(lineNo, `invalid cell address ${rawAddress}`)
    }
    // Reject anything that isn't purely letters followed by digits.
    if (!/^[A-Za-z]+[0-9]+$/.test(rawAddress)) {
      throw new SheetError(lineNo, `invalid cell address ${rawAddress}`)
    }

    const key = `${parsed.letters}${parsed.row}`
    if (cells.has(key)) {
      throw new SheetError(lineNo, `cell ${key} is declared twice`)
    }
    cells.set(key, { content, col: parsed.col, row: parsed.row, line: lineNo })
  })

  return cells
}
"}

