{"file_path":"src/values.js","content":"/**
 * The value model shared by literals and formula evaluation: a number,
 * text, a boolean, or an error token.
 */

export const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

export const ERR_DIV0 = err('#DIV/0!')
export const ERR_REF = err('#REF!')
export const ERR_VALUE = err('#VALUE!')
export const ERR_CYCLE = err('#CYCLE!')
export const ERR_NAME = err('#NAME?')
export const ERR_ERR = err('#ERR!')

const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

/** Parse a literal (non-formula) cell content into a Value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_RE.test(content)) return num(parseFloat(content))
  if (ERROR_TOKENS.has(content)) return err(content)
  return text(content)
}

/** Read a Value as a number for arithmetic, or ERR_VALUE if it can't be. */
export function toNumber(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'text') return ERR_VALUE
  return v
}

const RANK = { num: 0, text: 1, bool: 2 }

/** -1, 0, or 1 comparing two non-error Values per the spec's total order. */
export function compareValues(a, b) {
  if (RANK[a.t] !== RANK[b.t]) return RANK[a.t] < RANK[b.t] ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  const an = a.v ? 1 : 0
  const bn = b.v ? 1 : 0
  return an - bn
}
"}

