    this.asts.set(address, ast)
    return ast
  }

  /** The Value of a declared or default (0) cell, given its column/row. */
  evaluateCell(col, row) {
    const address = cellKey(col, row)
    return this.evaluate(address)
  }

  evaluate(address) {
    if (this.state.get(address) === 'done') return this.cache.get(address)
    if (this.state.get(address) === 'progress') {
      const idx = this.stack.indexOf(address)
      for (let i = idx; i < this.stack.length; i++) {
        this.cache.set(this.stack[i], ERR_CYCLE)
        this.state.set(this.stack[i], 'done')
      }
      return ERR_CYCLE
    }

    const cell = this.cells.get(address)
    if (!cell) {
      this.cache.set(address, num(0))
      this.state.set(address, 'done')
      return num(0)
    }

    this.state.set(address, 'progress')
    this.stack.push(address)
    const result = this.computeCell(cell)
    this.stack.pop()

    if (this.state.get(address) === 'done') return this.cache.get(address)
    this.cache.set(address, result)
    this.state.set(address, 'done')
    return result
  }

  computeCell(cell) {
    if (!cell.content.startsWith('=')) return parseLiteral(cell.content)
    const ast = this.getAst(cellKey(cell.col, cell.row))
    if (!ast) return ERR_ERR
    return this.evalNode(ast)
  }

  evalNode(node) {
    switch (node.type) {
      case 'number':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'address':
        return this.evalAddress(node.word)
      case 'unary':
        return this.evalUnary(node)
      case 'binary':
        return this.evalBinary(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  evalAddress(word) {
    const parsed = parseWord(word)
    if (!parsed.inRange) return ERR_REF
    return this.evaluateCell(parsed.col, parsed.row)
  }

  evalUnary(node) {
    const v = this.evalNode(node.operand)
    if (v.t === 'err') return v
    const n = toNumber(v)
    if (n.t === 'err') return n
    const result = node.op === '-' ? -n.v : n.v
    if (!Number.isFinite(result)) return ERR_DIV0
    return num(result)
  }

  evalBinary(node) {
    const isCmp = ['=', '<>', '<', '<=', '>', '>='].includes(node.op)
    const lv = this.evalNode(node.left)
    if (lv.t === 'err') return lv
    const rv = this.evalNode(node.right)
    if (rv.t === 'err') return rv

    if (isCmp) {
      const c = compareValues(lv, rv)
      switch (node.op) {
        case '=':
          return bool(c === 0)
        case '<>':
          return bool(c !== 0)
        case '<':
          return bool(c < 0)
        case '<=':
          return bool(c <= 0)
        case '>':
          return bool(c > 0)
        case '>=':
          return bool(c >= 0)
      }
    }

    const ln = toNumber(lv)
    if (ln.t === 'err') return ln
    const rn = toNumber(rv)
    if (rn.t === 'err') return rn

    let result
    switch (node.op) {
      case '+':
        result = ln.v + rn.v
        break
      case '-':
        result = ln.v - rn.v
        break
      case '*':
        result = ln.v * rn.v
        break
      case '/':
        if (rn.v === 0) return ERR_DIV0
        result = ln.v / rn.v
        break
      case '^':
        result = Math.pow(ln.v, rn.v)
        break
    }
    if (!Number.isFinite(result)) return ERR_DIV0
    return num(result)
  }

  /** Every Value an argument slot contributes (a range yields many). */
  collectSlot(argNode) {
    if (argNode.type === 'range') {
      const cells = expandRange(argNode.from, argNode.to)
      return cells.map(({ col, row }) =>
        isAddressableCell(col, row) ? this.evaluateCell(col, row) : ERR_REF,
      )
    }
    return [this.evalNode(argNode)]
  }

  evalCall(node) {
    const { name, args } = node
    if (name === 'ABS') {
      if (args.length !== 1) return ERR_ERR
      return this.applyScalar(args[0], (v) => {
        const result = Math.abs(v)
        return Number.isFinite(result) ? num(result) : ERR_DIV0
      })
    }
    if (name === 'IF') {
      if (args.length !== 3) return ERR_ERR
      return this.evalIf(args)
    }
    if (VARIADIC_FUNCS.has(name)) {
      if (args.length < 1) return ERR_ERR
      const values = args.flatMap((a) => this.collectSlot(a))
      return this.applyAggregate(name, values)
    }
    return ERR_NAME
  }

  applyScalar(argNode, fn) {
    const values = this.collectSlot(argNode)
    const errValue = values.find((v) => v.t === 'err')
    if (errValue) return errValue
    if (values.length !== 1) return ERR_VALUE
    const n = toNumber(values[0])
    if (n.t === 'err') return n
    return fn(n.v)
  }

  evalIf(args) {
    const condValues = this.collectSlot(args[0])
    const condErr = condValues.find((v) => v.t === 'err')
    if (condErr) return condErr
    if (condValues.length !== 1) return ERR_VALUE
    const condValue = condValues[0]
    let cond
    if (condValue.t === 'bool') cond = condValue.v
    else if (condValue.t === 'num') cond = condValue.v !== 0
    else return ERR_VALUE

    const branch = cond ? args[1] : args[2]
    const branchValues = this.collectSlot(branch)
    const branchErr = branchValues.find((v) => v.t === 'err')
    if (branchErr) return branchErr
    if (branchValues.length !== 1) return ERR_VALUE
    return branchValues[0]
  }

  applyAggregate(name, values) {
    const errValue = values.find((v) => v.t === 'err')
    if (errValue) return errValue
    if (name === 'COUNT') return num(values.filter((v) => v.t === 'num').length)

    const nums = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.t === 'err') return n
      nums.push(n.v)
    }
    let result
    if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
    else if (name === 'MIN') result = Math.min(...nums)
    else if (name === 'MAX') result = Math.max(...nums)
    else if (name === 'AVG') result = nums.reduce((a, b) => a + b, 0) / nums.length
    return Number.isFinite(result) ? num(result) : ERR_DIV0
  }
}
