 * Collects the cells a formula names directly, ranges expanded, for the
 * `deps` command.
 */

import { parseWord, cellKey, isAddressableCell } from './address.js'
import { expandRange } from './evaluate.js'

/** Ordered, deduplicated list of addressable cells a parsed AST names. */
export function collectDeps(ast) {
  const seen = new Map() // key -> {col,row}
  walk(ast, seen)
  return [...seen.values()]
    .sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
    .map(({ col, row }) => cellKey(col, row))
}

function add(seen, col, row) {
  if (!isAddressableCell(col, row)) return
  seen.set(`${col},${row}`, { col, row })
}

function walk(node, seen) {
  switch (node.type) {
    case 'number':
    case 'bool':
      return
    case 'address': {
      const parsed = parseWord(node.word)
      if (parsed.inRange) add(seen, parsed.col, parsed.row)
      return
    }
    case 'unary':
      walk(node.operand, seen)
      return
    case 'binary':
      walk(node.left, seen)
      walk(node.right, seen)
      return
    case 'call':
      for (const arg of node.args) walk(arg, seen)
      return
    case 'range':
      for (const { col, row } of expandRange(node.from, node.to)) add(seen, col, row)
      return
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}
"}

