{"file_path":"src/format.js","content":"/**
 * Formats a Value for the `values` command's output.
 */

function roundToSignificant(x, sig) {
  if (x === 0 || !Number.isFinite(x)) return x
  return Number(x.toPrecision(sig))
}

export function formatValue(value) {
  switch (value.t) {
    case 'num':
      return String(roundToSignificant(value.v, 10))
    case 'text':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'err':
      return value.v
    default:
      throw new Error(`unknown value type ${value.t}`)
  }
}
"}

